-- The demo congregation in English, for the help's English captures (scripts/help-captures/README.md). Names, parts,
-- sections, roles and document titles are data, not messages: run this on a copy of the French scratch database,
-- never on the French one and never on a real one. Terms follow docs/development/translation-glossary.md and the
-- app's English seed names.
DO $$ BEGIN
  IF current_database() NOT LIKE '%captures%' THEN RAISE EXCEPTION 'Not a capture database: %', current_database(); END IF;
END $$;

UPDATE "Congregation" SET name = 'My Congregation', "displayName" = CASE WHEN "displayName" IS NULL THEN NULL ELSE 'My Congregation' END, locale = 'en';
UPDATE "EventTemplate" t SET "name" = v.en FROM (VALUES ('Réunion de semaine', 'Midweek meeting'), ('Réunion du week-end', 'Weekend meeting'), ('Mémorial', 'Memorial'), ('Absence', 'Absence'), ('Autre événement', 'Other event')) AS v(fr, en) WHERE t."name" = v.fr;
UPDATE "Event" t SET "name" = v.en FROM (VALUES ('Réunion de semaine', 'Midweek meeting'), ('Réunion du week-end', 'Weekend meeting'), ('Mémorial', 'Memorial'), ('Absence', 'Absence'), ('Autre événement', 'Other event'), ('Déplacement professionnel', 'Business trip'), ('Visite familiale', 'Family visit'), ('Vacances', 'Vacation'), ('Congé', 'Time off'), ('Indisponible', 'Unavailable')) AS v(fr, en) WHERE t."name" = v.fr;
