UPDATE "BuildingEntrance" SET notes = 'Mailboxes in the hall. The caretaker is there in the morning, except on Wednesdays.' WHERE notes LIKE 'Boîtes aux lettres%';

-- The demo accounts read the app in English.
UPDATE "UserAccount" SET locale = 'en' WHERE email LIKE '%@demo.unitae.app';
